int RunInteractionProbe(const fs::path& directory){
    // Isolated native UI tests: do not hide Explorer or launch/adopt user applications.
    if(fs::exists(directory/L"settings.json")||fs::exists(directory/L"shell-original.json"))return 2;
    Application app(directory,true);app.monitors=GetMonitors();if(app.monitors.empty())return 2;
    WNDCLASSW eventsClass{};eventsClass.hInstance=GetModuleHandleW(nullptr);eventsClass.lpfnWndProc=Application::EventProc;eventsClass.lpszClassName=L"GoodView.InteractionProbeEvents";RegisterClassW(&eventsClass);
    app.events=CreateWindowExW(0,eventsClass.lpszClassName,L"",0,0,0,0,0,HWND_MESSAGE,nullptr,eventsClass.hInstance,&app);if(!app.events)return 2;
    InteractionProbe probe{app};probe.Run();probe.AuditVisibleWindows();probe.Check(probe.captionIssues.Size()==0,L"command captions fit across launcher appearance index and widget editors");WriteAtomic(directory/L"caption-audit.json",std::wstring(probe.captionIssues.Stringify()));json::JsonObject report;report.SetNamedValue(L"passed",json::JsonValue::CreateBooleanValue(probe.passed));report.SetNamedValue(L"checks",probe.checks);
    if(!WriteAtomic(directory/L"interaction-smoke.json",std::wstring(report.Stringify())))return 2;return probe.passed?0:1;
}
